typedef enum {
    Z_OPENRESULT_TAG_OK,
    Z_OPENRESULT_TAG_ERR,
} z_t1476_tag_t;
struct z_t1476_t {
    z_t1476_tag_t tag;
    void* data;
};
static void z_t1476_destroy(z_t1476_t* u) {
    if (!u) return;
    if (!u->data) return;
    switch (u->tag) {
        case Z_OPENRESULT_TAG_OK:
            z_t77_free((z_t77_t*)u->data);
            free(u->data);
            break;
        case Z_OPENRESULT_TAG_ERR:
            z_t1477_destroy((z_t1477_t*)u->data);
            free(u->data);
            break;
        default: break;
    }
}

